async function natural_language_search(params, userSettings, resources) {
  (function ensureEnvironmentPolyfills() {
    const root = (typeof globalThis !== 'undefined') ? globalThis :
                 (typeof window !== 'undefined') ? window :
                 (typeof self !== 'undefined') ? self :
                 (typeof global !== 'undefined') ? global : this;
    if (!root) return;
    if (typeof root.structuredClone !== 'function') {
      root.structuredClone = function(val, seen = new Map()) {
        if (val === null || typeof val !== 'object') return val;
        if (val instanceof Date) return new Date(val.getTime());
        if (val instanceof RegExp) return new RegExp(val.source, val.flags);
        if (typeof ArrayBuffer !== 'undefined' && val instanceof ArrayBuffer) return val.slice(0);
        if (typeof ArrayBuffer !== 'undefined' && ArrayBuffer.isView(val)) {
          if (typeof DataView !== 'undefined' && val instanceof DataView) {
            return new DataView(val.buffer.slice(val.byteOffset, val.byteOffset + val.byteLength));
          }
          return new val.constructor(val.buffer.slice(val.byteOffset, val.byteOffset + val.byteLength));
        }
        if (seen.has(val)) return seen.get(val);
        if (typeof Map !== 'undefined' && val instanceof Map) {
          const copy = new Map();
          seen.set(val, copy);
          val.forEach((v, k) => copy.set(root.structuredClone(k, seen), root.structuredClone(v, seen)));
          return copy;
        }
        if (typeof Set !== 'undefined' && val instanceof Set) {
          const copy = new Set();
          seen.set(val, copy);
          val.forEach(v => copy.add(root.structuredClone(v, seen)));
          return copy;
        }
        if (Array.isArray(val)) {
          const copy = [];
          seen.set(val, copy);
          for (let i = 0; i < val.length; i++) copy[i] = root.structuredClone(val[i], seen);
          return copy;
        }
        try {
          const copy = Object.create(Object.getPrototypeOf(val));
          seen.set(val, copy);
          for (const key of Reflect.ownKeys(val)) copy[key] = root.structuredClone(val[key], seen);
          return copy;
        } catch (e) {
          return val;
        }
      };
    }
  })();

  const { query, documentUrl, contextMetadata, outputIntent, detailMode } = params;
  const proxyBase = (userSettings.proxyUrl || userSettings.workerUrl || 'https://unified-proxy.creativeappmaking.workers.dev').replace(/\/$/, '');

  const vaultRef = (typeof vault !== 'undefined' && vault) || (resources && resources.vault);
  const geminiApiKey = userSettings.google_api_key || userSettings.gemini_api_key || (vaultRef && (vaultRef.getSecret('GOOGLE_API_KEY') || vaultRef.getSecret('GEMINI_API_KEY')));
  const searchApiKey = userSettings.search_api_key || userSettings.exa_api_key || (vaultRef && vaultRef.getSecret('EXA_API_KEY'));
  const actionOnError = userSettings.action_on_error || 'return_diagnostic_json';

  const geminiProxyUrl = `${proxyBase}/proxy/https://generativelanguage.googleapis.com/v1beta/interactions`;
  const geminiDirectUrl = 'https://generativelanguage.googleapis.com/v1beta/interactions';
  const searchProxyUrl = `${proxyBase}/exa/search`;
  const searchDirectUrl = 'https://api.exa.ai/search';
  const today = new Date().toISOString().split('T')[0];
  const currentYear = today.split('-')[0];
  let transportState = 'healthy';

  function sleep(ms) { return new Promise(resolve => setTimeout(resolve, ms)); }
  function clamp(num, min, max) { return Math.max(min, Math.min(max, num)); }
  function unique(arr) { return Array.from(new Set((arr || []).filter(Boolean))); }
  function toArray(v) { return Array.isArray(v) ? v.filter(Boolean) : []; }
  function truncate(text, max) { return (!text || text.length <= max) ? (text || '') : text.slice(0, max); }

  function normalizeUrl(url) {
    try {
      const u = new URL(url);
      u.hash = '';
      u.search = '';
      return u.toString().replace(/\/+$/, '/').replace(/\/$/, '');
    } catch (e) { return url || ''; }
  }

  function safeDomain(url) {
    try { return new URL(url).hostname.replace(/^www\./, ''); } catch (e) { return 'unknown'; }
  }

  function cleanTextPreserveLines(text) {
    if (!text) return '';
    return String(text)
      .replace(/\r/g, '\n')
      .replace(/\u0000/g, '')
      .replace(/\t/g, '  ')
      .replace(/[ \u00A0]+\\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }

  function extractCleanTextFromHtml(htmlString) {
    if (!htmlString) return '';
    if (typeof DOMParser !== 'undefined') {
      try {
        const parser = new DOMParser();
        const doc = parser.parseFromString(htmlString, 'text/html');
        doc.querySelectorAll('script, style, iframe, nav, footer, header, noscript, svg, img, form').forEach(el => el.remove());
        const mainContent = doc.querySelector('article, main, #content, .content, #main-content') || doc.body;
        if (mainContent) {
          const text = mainContent.innerText || mainContent.textContent || '';
          return cleanTextPreserveLines(text).slice(0, 35000);
        }
      } catch (e) {}
    }
    return String(htmlString)
      .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
      .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
      .replace(/<nav\b[^<]*(?:(?!<\/nav>)<[^<]*)*<\/nav>/gi, '')
      .replace(/<footer\b[^<]*(?:(?!<\/footer>)<[^<]*)*<\/footer>/gi, '')
      .replace(/<header\b[^<]*(?:(?!<\/header>)<[^<]*)*<\/header>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/gi, ' ')
      .replace(/&amp;/gi, '&')
      .replace(/&lt;/gi, '<')
      .replace(/&gt;/gi, '>')
      .replace(/&quot;/gi, '"')
      .replace(/[ \t]+/g, ' ')
      .replace(/\n\s*\n/g, '\n\n')
      .slice(0, 35000)
      .trim();
  }

  // --- ROBUST PDF & SPREADSHEET INITIALIZERS ---
  async function loadPdfJS() {
    const target = (typeof globalThis !== 'undefined') ? globalThis :
                   (typeof window !== 'undefined') ? window : this;
    if (target.pdfjsLib) return target.pdfjsLib;

    const workerUrl = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.16.105/pdf.worker.min.js';
    const libUrl = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.16.105/pdf.min.js';

    try {
      const [resWorker, resLib] = await Promise.all([
        fetch(workerUrl),
        fetch(libUrl)
      ]);
      const [codeWorker, codeLib] = await Promise.all([
        resWorker.text(),
        resLib.text()
      ]);

      // Execute worker FIRST into target context to establish WorkerMessageHandler
      const fnWorker = new Function('require', 'exports', 'module', codeWorker);
      fnWorker.call(target, () => ({}), {}, { exports: {} });

      // Execute main library
      const fnLib = new Function('require', 'exports', 'module', codeLib);
      fnLib.call(target, () => ({}), {}, { exports: {} });

      const pdfjs = target.pdfjsLib || (typeof window !== 'undefined' && window.pdfjsLib);
      if (pdfjs) {
        // Setup Blob Worker URL to defeat cross-origin restriction in browsers
        if (typeof Blob !== 'undefined' && typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function') {
          try {
            const blob = new Blob([codeWorker], { type: 'application/javascript' });
            pdfjs.GlobalWorkerOptions.workerSrc = URL.createObjectURL(blob);
          } catch (blobErr) {
            pdfjs.GlobalWorkerOptions.workerSrc = workerUrl;
          }
        } else {
          pdfjs.GlobalWorkerOptions.workerSrc = workerUrl;
        }
        return pdfjs;
      }
    } catch (e) {}

    // Fallback: DOM script insertion for browser environments
    if (typeof document !== 'undefined') {
      return new Promise((resolve) => {
        const script = document.createElement('script');
        script.src = libUrl;
        script.onload = () => {
          if (window.pdfjsLib) {
            window.pdfjsLib.GlobalWorkerOptions.workerSrc = workerUrl;
            resolve(window.pdfjsLib);
          } else {
            resolve(null);
          }
        };
        script.onerror = () => resolve(null);
        document.head.appendChild(script);
      });
    }

    return null;
  }

  async function loadSheetJS() {
    const target = (typeof globalThis !== 'undefined') ? globalThis :
                   (typeof window !== 'undefined') ? window : this;
    if (target.XLSX) return target.XLSX;

    const xlsxUrl = 'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
    try {
      const res = await fetch(xlsxUrl);
      const code = await res.text();
      const fn = new Function('window', 'global', 'globalThis', code);
      fn(target, target, target);
      return target.XLSX || (typeof window !== 'undefined' && window.XLSX) || null;
    } catch (e) {}

    if (typeof document !== 'undefined') {
      return new Promise((resolve) => {
        const script = document.createElement('script');
        script.src = xlsxUrl;
        script.onload = () => resolve(window.XLSX || null);
        script.onerror = () => resolve(null);
        document.head.appendChild(script);
      });
    }
    return null;
  }

  async function extractTextFromPdfData(arrayBuffer) {
    try {
      const pdfjs = await loadPdfJS();
      if (!pdfjs) return '[PDF.js parser could not be initialized in this runtime environment.]';
      const data = arrayBuffer instanceof Uint8Array ? arrayBuffer : new Uint8Array(arrayBuffer);
      const loadingTask = pdfjs.getDocument({
        data: data,
        disableFontFace: true,
        isEvalSupported: false,
        useSystemFonts: false
      });
      const pdf = await loadingTask.promise;
      let fullText = '';
      const maxPages = Math.min(pdf.numPages, 16);
      for (let pageNum = 1; pageNum <= maxPages; pageNum++) {
        const page = await pdf.getPage(pageNum);
        const textContent = await page.getTextContent();
        const pageText = textContent.items.map(item => item.str).join(' ');
        fullText += `[Page ${pageNum} of ${pdf.numPages}]\n${pageText}\n\n`;
      }
      return cleanTextPreserveLines(fullText);
    } catch (err) {
      return `[PDF text extraction error: ${err.message}]`;
    }
  }

  async function extractTextFromExcelData(arrayBuffer) {
    try {
      const xlsx = await loadSheetJS();
      if (!xlsx) return '[SheetJS parser could not be initialized in this runtime environment.]';
      const workbook = xlsx.read(arrayBuffer, { type: 'array' });
      let fullText = '';
      const sheetNames = workbook.SheetNames.slice(0, 5);
      for (const sheetName of sheetNames) {
        const sheet = workbook.Sheets[sheetName];
        const csv = xlsx.utils.sheet_to_csv(sheet);
        fullText += `[Spreadsheet Tab: ${sheetName}]\n${csv.slice(0, 18000)}\n\n`;
      }
      return cleanTextPreserveLines(fullText);
    } catch (err) {
      return `[Excel text extraction error: ${err.message}]`;
    }
  }

  async function fetchAndHydrateDocument(url) {
    const fetchTargets = [
      proxyBase ? `${proxyBase}/proxy/${url}` : null,
      url
    ].filter(Boolean);

    for (const target of fetchTargets) {
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 20000);
        const res = await fetch(target, {
          signal: controller.signal,
          headers: {
            'Accept': 'application/pdf,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv,text/html,*/*'
          }
        });
        clearTimeout(timeoutId);
        if (!res.ok) continue;

        const contentType = (res.headers.get('content-type') || '').toLowerCase();
        const isPdf = contentType.includes('application/pdf') || url.toLowerCase().includes('.pdf');
        const isExcel = contentType.includes('spreadsheet') || contentType.includes('excel') || contentType.includes('csv') || /\.(xlsx|xls|csv)(\?|$)/i.test(url);

        if (isPdf) {
          const arrayBuffer = await res.arrayBuffer();
          const text = await extractTextFromPdfData(arrayBuffer);
          return { type: 'pdf', text, success: text.length > 50 && !text.startsWith('[PDF text extraction error') };
        } else if (isExcel) {
          const arrayBuffer = await res.arrayBuffer();
          const text = await extractTextFromExcelData(arrayBuffer);
          return { type: 'excel', text, success: text.length > 30 && !text.startsWith('[Excel text extraction error') };
        } else {
          const raw = await res.text();
          const text = extractCleanTextFromHtml(raw);
          return { type: 'html', text, success: text.length > 50 };
        }
      } catch (e) {}
    }
    return { type: 'unknown', text: '', success: false };
  }

  function lineLooksCode(line) {
    if (!line) return false;
    const trimmed = line.trim();
    if (!trimmed) return false;
    if (/^(import |export |const |let |var |function |async function |class |interface |type |enum |SELECT |INSERT |UPDATE |DELETE |CREATE |ALTER |curl |npm |pnpm |yarn |docker |kubectl |terraform |resource |module |FROM |WHERE )/i.test(trimmed)) return true;
    if (/=>|\{\s*$|^\}|;\s*$|<\/?[A-Za-z]|Response\.json|NextResponse|await |return |console\.|\s{2,}[A-Za-z0-9_$]/.test(line)) return true;
    return false;
  }

  function lineLooksList(line) {
    if (!line) return false;
    const trimmed = line.trim();
    return /^([-*•]|[|]|_Private|\d+[.)]|[A-Za-z]\.)\s+/.test(trimmed) || trimmed.startsWith('|');
  }

  function lineLooksLegal(line) {
    if (!line) return false;
    return /\b(section|article|clause|statute|regulation|subsection|paragraph|shall|pursuant|effective date|whereas|hereby|means|codified|u\.s\.c\.)\b/i.test(line);
  }

  function extractTextFromInteraction(data) {
    if (!data) return '';
    if (typeof data.output_text === 'string' && data.output_text) return data.output_text;
    if (!data.steps) return '';
    let textParts = [];
    for (const step of data.steps) {
      if (step.type === 'model_output' && step.content) {
        for (const block of step.content) {
          if (block.type === 'text' && block.text) textParts.push(block.text);
        }
      }
    }
    return textParts.join('');
  }

  async function callGemini(systemInstruction, userPrompt, responseSchema, maxOutputTokens) {
    const payload = {
      model: 'gemini-3.5-flash-lite',
      input: userPrompt,
      system_instruction: systemInstruction
    };
    if (maxOutputTokens) payload.generation_config = { max_output_tokens: maxOutputTokens };
    if (responseSchema) {
      payload.response_format = {
        type: 'text',
        mime_type: 'application/json',
        schema: responseSchema
      };
    }

    const headers = {
      'Content-Type': 'application/json',
      'x-goog-api-key': geminiApiKey,
      'Api-Revision': '2026-05-20'
    };

    const endpoints = [geminiProxyUrl, geminiDirectUrl];
    for (const endpoint of endpoints) {
      try {
        const res = await fetch(endpoint, { method: 'POST', headers, body: JSON.stringify(payload) });
        if (res.ok) {
          const data = await res.json();
          return extractTextFromInteraction(data);
        }
      } catch (e) {}
    }
    return null;
  }

  function tokenizeNeedles(routePlan) {
    const terms = [];
    terms.push(...toArray(routePlan.key_terms));
    const depNames = Object.keys((contextMetadata && contextMetadata.dependencyManifest) || {});
    terms.push(...depNames);
    const q = String(query || '').split(/[^A-Za-z0-9_.#:-]+/).filter(t => t && t.length > 2);
    terms.push(...q.slice(0, 16));
    return unique(terms.map(t => String(t).trim()).filter(t => t.length > 1)).slice(0, 24);
  }

  function countKeywordHits(text, terms) {
    if (!text) return 0;
    const lower = text.toLowerCase();
    let score = 0;
    for (const term of terms) {
      const t = String(term).toLowerCase();
      if (!t) continue;
      if (lower.includes(t)) score += Math.min(3, lower.split(t).length - 1);
    }
    return score;
  }

  function chunkText(text, targetSize) {
    const cleaned = cleanTextPreserveLines(text);
    if (!cleaned) return [];
    const paragraphs = cleaned.split(/\n\s*\n/).filter(Boolean);
    if (paragraphs.length === 0) return [cleaned.slice(0, targetSize)];

    const chunks = [];
    let current = '';
    for (const para of paragraphs) {
      const isTableOrList = para.includes('|') || para.split('\n').some(lineLooksList);
      const candidate = current ? `${current}\n\n${para}` : para;
      if (isTableOrList && candidate.length <= targetSize * 1.5) {
        current = candidate;
      } else if (candidate.length <= targetSize) {
        current = candidate;
      } else {
        if (current) chunks.push(current);
        if (para.length <= targetSize) {
          current = para;
        } else {
          for (let i = 0; i < para.length; i += targetSize) {
            chunks.push(para.slice(i, i + targetSize));
          }
          current = '';
        }
      }
    }
    if (current) chunks.push(current);
    return chunks;
  }

  function scoreChunk(chunk, routePlan, searchBranch, isHydratedDoc) {
    const terms = tokenizeNeedles(routePlan);
    const lines = chunk.split('\n');
    const codeLines = lines.filter(lineLooksCode).length;
    const listLines = lines.filter(lineLooksList).length;
    const legalLines = lines.filter(lineLooksLegal).length;
    const keywordHits = countKeywordHits(chunk, terms);
    const lower = chunk.toLowerCase();
    const boundaryHits = (lower.match(/\b(but|except|unless|however|warning|caveat|limitation|issue|deprecated|broken|note|workaround|fix|hack|solved|solution|resolved)\b/g) || []).length;
    let score = keywordHits * 3 + boundaryHits * 2;

    if (routePlan.need_class === 'code_extract') score += codeLines * 5 + listLines;
    if (routePlan.need_class === 'forum_troubleshoot') score += (boundaryHits * 4) + (listLines * 2) + (codeLines * 2);
    if (routePlan.need_class === 'enumeration_extract' || routePlan.need_class === 'procedure_extract') score += listLines * 4 + codeLines;
    if (routePlan.need_class === 'verbatim_extract' || outputIntent === 'VERBATIM_STATUTE') score += legalLines * 5;
    if (routePlan.need_class === 'version_pin' || routePlan.need_class === 'contradiction_audit') score += boundaryHits * 3;
    if (searchBranch === 'adversarial') score += 1;
    if (isHydratedDoc) score += 15;
    return score;
  }

  function selectWindowsForSource(source, routePlan, budgetChars) {
    const targetChunk = routePlan.need_class === 'code_extract' ? 2400 : routePlan.breadth_mode === 'exhaustive' ? 3200 : 1800;
    const chunks = chunkText(source.text || '', targetChunk);
    if (chunks.length === 0) return [];

    const isHydratedDoc = source.role === 'official_document' || source.is_hydrated;
    const scored = chunks.map((chunk, idx) => ({
      idx,
      text: chunk,
      score: scoreChunk(chunk, routePlan, source.branch, isHydratedDoc),
      codeLines: chunk.split('\n').filter(lineLooksCode).length,
      listLines: chunk.split('\n').filter(lineLooksList).length,
      legalLines: chunk.split('\n').filter(lineLooksLegal).length,
      isTable: chunk.includes('|') || (chunk.includes(',') && chunk.split('\n').length > 4)
    }));

    scored.forEach(c => {
      if (/disclaimer|disclosure|acknowledgement|funding|conflict of interest|declaration of interest|fictional|fictitious|made up/i.test(c.text)) {
        c.score += 1000;
      }
    });

    scored.sort((a, b) => b.score - a.score || a.idx - b.idx);
    const maxWindows = routePlan.breadth_mode === 'exhaustive' || isHydratedDoc ? 6 : 4;
    const chosen = [];
    let spent = 0;
    const usedIdx = new Set();

    for (const candidate of scored) {
      if (chosen.length >= maxWindows || spent >= budgetChars) break;
      if (usedIdx.has(candidate.idx)) continue;
      const remaining = budgetChars - spent;
      const pickedText = truncate(candidate.text, remaining);
      if (!pickedText) continue;

      let kind = 'context';
      if (source.role === 'official_document' && (candidate.legalLines >= 1 || outputIntent === 'VERBATIM_STATUTE')) kind = 'verbatim';
      else if (source.role === 'official_document' && candidate.isTable) kind = 'table';
      else if (routePlan.need_class === 'code_extract' && candidate.codeLines >= 2) kind = 'code';
      else if (routePlan.need_class === 'forum_troubleshoot' && (candidate.text.includes('workaround') || candidate.text.includes('fix') || candidate.text.includes('solved'))) kind = 'solution';
      else if ((routePlan.need_class === 'enumeration_extract' || routePlan.need_class === 'procedure_extract') && candidate.listLines >= 2) kind = 'list';
      else if ((routePlan.need_class === 'verbatim_extract' || outputIntent === 'VERBATIM_STATUTE') && candidate.legalLines >= 1) kind = 'verbatim';
      else if (source.branch === 'adversarial' || /\b(but|except|unless|however|warning|caveat|limitation|issue|deprecated|broken|note)\b/i.test(candidate.text)) kind = 'boundary';
      else kind = 'support';

      chosen.push({ sourceId: source.id, kind, text: pickedText });
      usedIdx.add(candidate.idx);
      spent += pickedText.length;
    }

    if (chosen.length === 0) {
      chosen.push({ sourceId: source.id, kind: 'support', text: truncate(source.text || '', budgetChars) });
    }
    return chosen;
  }

  function classifySourceRole(url, title) {
    const domain = safeDomain(url);
    const titleLower = String(title || '').toLowerCase();
    const urlLower = String(url || '').toLowerCase();
    if (/\.(pdf|xlsx|xls|csv)(\?|$)/i.test(urlLower) || urlLower.includes('/pdf/')) return 'official_document';
    if (/github\.com$/.test(domain)) return 'github';
    if (/docs|developer|developers|reference|manual|api/.test(domain) || /documentation|reference|api/i.test(titleLower)) return 'official_docs';
    if (/wikipedia\.org$/.test(domain)) return 'encyclopedia';
    if (/reddit\.com$|stackoverflow\.com$|stackexchange\.com$|discord\.com$|discourse|forums|community/.test(domain) || /forum|discussion|thread/i.test(titleLower)) return 'forum';
    return 'web';
  }

  function classifySourceCredibility(url, title, text, isHydratedDoc) {
    const domain = safeDomain(url);
    const urlLower = String(url || '').toLowerCase();
    const titleLower = String(title || '').toLowerCase();
    const textLower = String(text || '').toLowerCase();

    if (urlLower.includes('preprint') || titleLower.includes('preprint') || domain.includes('preprints.org') || textLower.includes('preprint server')) {
      return { level: 2, label: 'Tertiary Source', rationale: 'Unreviewed academic preprint. Must be treated with extreme clinical skepticism.' };
    }

    const primarySuffixes = ['.gov', '.mil', '.gov.uk', '.europa.eu', '.senate.gov', '.house.gov'];
    for (const suffix of primarySuffixes) {
      if (domain === suffix.substring(1) || domain.endsWith(suffix)) {
        return { level: 0, label: 'Primary Source', rationale: `Verified government or legal domain: ${domain}` };
      }
    }

    if (isHydratedDoc && (urlLower.endsWith('.pdf') || urlLower.endsWith('.xlsx') || urlLower.endsWith('.csv'))) {
      if (domain.endsWith('.edu') || domain.includes('court') || domain.includes('sec.gov') || domain.includes('treasury')) {
        return { level: 0, label: 'Primary Source', rationale: `Hydrated primary document archive: ${domain}` };
      }
    }

    const primaryDomains = [
      'congress.gov', 'federalregister.gov', 'supremecourt.gov', 'pacer.uscourts.gov',
      'legislation.gov.uk', 'data.gov', 'census.gov', 'bls.gov', 'fred.stlouisfed.org',
      'data.worldbank.org', 'clinicaltrials.gov'
    ];
    if (primaryDomains.includes(domain)) return { level: 0, label: 'Primary Source', rationale: `Matches primary institutional database: ${domain}` };
    if (/\b10\.\d{4,}\//.test(url) || urlLower.includes('doi.org/10.')) return { level: 0, label: 'Primary Source', rationale: 'Matches DOI publication pattern' };

    const academicDomains = ['arxiv.org', 'pubmed.ncbi.nlm.nih.gov', 'doi.org', 'sciencedirect.com', 'ieee.org', 'nature.com', 'springer.com', 'researchgate.net'];
    if (academicDomains.includes(domain) || academicDomains.some(d => domain.endsWith('.' + d))) {
      return { level: 0, label: 'Primary Source', rationale: `Peer-reviewed scientific repository: ${domain}` };
    }

    if (domain === 'github.com' && urlLower.includes('/blob/')) return { level: 0, label: 'Primary Source', rationale: 'Matches raw code repository source file' };

    const eduSuffixes = ['.edu', '.ac.uk', '.edu.au', '.edu.cn', '.edu.sg', '.edu.hk'];
    if (eduSuffixes.some(suffix => domain === suffix.substring(1) || domain.endsWith(suffix)) || domain.includes('.edu.')) {
      return { level: 1, label: 'Secondary Source', rationale: `Academic or educational institution: ${domain}` };
    }

    if (/museum\b|smithsonian|airandspace/i.test(domain) || /museum|smithsonian/i.test(titleLower)) {
      return { level: 1, label: 'Secondary Source', rationale: `Museum or historical reference archive: ${domain}` };
    }

    const majorNewsDomains = [
      'reuters.com', 'apnews.com', 'npr.org', 'bbc.com', 'bbc.co.uk', 'pbs.org', 'propublica.org',
      'theguardian.com', 'nytimes.com', 'washingtonpost.com', 'wsj.com', 'politico.com',
      'axios.com', 'vox.com', 'theatlantic.com', 'newyorker.com', 'economist.com'
    ];
    if (majorNewsDomains.some(outlet => domain === outlet || domain.endsWith('.' + outlet))) {
      return { level: 1, label: 'Secondary Source', rationale: `Established editorial news outlet: ${domain}` };
    }

    const pressReleaseDomains = ['prnewswire.com', 'businesswire.com', 'globenewswire.com', 'eurekalert.org'];
    if (pressReleaseDomains.includes(domain)) return { level: 1, label: 'Secondary Source', rationale: 'Press release distribution channel' };
    if (domain === 'wikipedia.org' || domain.endsWith('.wikipedia.org')) return { level: 1, label: 'Secondary Source', rationale: 'Wikipedia online encyclopedia' };

    const socialMediaDomains = ['reddit.com', 'twitter.com', 'x.com', 'facebook.com', 'medium.com', 'substack.com', 'youtube.com', 'tiktok.com'];
    if (socialMediaDomains.some(sm => domain === sm || domain.endsWith('.' + sm))) return { level: 2, label: 'Tertiary Source', rationale: 'Social media or user-generated blog platform' };
    if (domain.endsWith('.org')) return { level: 2, label: 'Tertiary Source', rationale: `Organization domain: ${domain}` };

    return { level: 3, label: 'Unclassified', rationale: `General web source: ${domain}. Veracity requires verification.` };
  }

  function buildCitationGraph(sources) {
    const citation_map = {};
    for (const s of sources) citation_map[s.id] = { cites: {} };

    const stopWords = new Set([
      'a', 'an', 'the', 'is', 'of', 'in', 'to', 'for', 'and', 'or', 'with', 'on', 'at', 'by',
      'from', 'as', 'into', 'through', 'during', 'before', 'after', 'above', 'below', 'between',
      'under', 'again', 'further', 'then', 'once', 'here', 'there', 'when', 'where', 'why', 'how',
      'all', 'both', 'each', 'few', 'more', 'most', 'other', 'some', 'such', 'no', 'nor', 'not', 'only',
      'own', 'same', 'so', 'than', 'too', 'very', 'just', 'also', 'now', 'about', 'up', 'out', 'if'
    ]);

    function extractKeywords(title) {
      if (!title) return [];
      return title.toLowerCase().split(/[^a-z0-9]+/).filter(w => w && w.length > 1 && !stopWords.has(w));
    }

    for (const A of sources) {
      if (!A.text) continue;
      const aTextLower = A.text.toLowerCase();
      for (const B of sources) {
        if (A.id === B.id) continue;
        const bCanonical = normalizeUrl(B.url);
        const bDomain = safeDomain(B.url);
        const bKeywords = extractKeywords(B.title);
        let citation_score = 0;
        const matches = [];
        if (bCanonical && A.text.includes(bCanonical)) { citation_score += 3; matches.push('Direct URL citation'); }
        if (bDomain && bDomain !== 'unknown' && bDomain.length > 3 && aTextLower.includes(bDomain)) { citation_score += 2; matches.push(`Domain-level reference: ${bDomain}`); }
        if (bKeywords && bKeywords.length >= 3) {
          let matchedCount = 0;
          for (const kw of bKeywords) { if (aTextLower.includes(kw)) matchedCount++; }
          if (matchedCount / bKeywords.length >= 0.6) { citation_score += 1; matches.push(`Title keyword overlap (${matchedCount}/${bKeywords.length} keywords)`); }
        }
        if (citation_score >= 3) citation_map[A.id].cites[B.id] = { score: citation_score, evidence: matches.join('; ') };
      }
    }

    const circular_chains = [];
    const visitedCycles = new Set();
    function findCyclesDFS(nodeId, path, visited) {
      const lastNode = path[path.length - 1];
      const neighbors = Object.keys(citation_map[lastNode]?.cites || {}).map(Number);
      for (const neighbor of neighbors) {
        const cycleStartIndex = path.indexOf(neighbor);
        if (cycleStartIndex !== -1) {
          const cycle = path.slice(cycleStartIndex);
          cycle.push(neighbor);
          const cycleNodes = cycle.slice(0, -1);
          const minVal = Math.min(...cycleNodes);
          const minIdx = cycleNodes.indexOf(minVal);
          const canonicalNodes = [...cycleNodes.slice(minIdx), ...cycleNodes.slice(0, minIdx)];
          canonicalNodes.push(minVal);
          const key = canonicalNodes.join(',');
          if (!visitedCycles.has(key)) {
            visitedCycles.add(key);
            circular_chains.push({ chain: canonicalNodes, description: canonicalNodes.map(id => `S${id}`).join('→') });
          }
        } else if (!visited.has(neighbor)) {
          visited.add(neighbor);
          findCyclesDFS(nodeId, [...path, neighbor], visited);
          visited.delete(neighbor);
        }
      }
    }

    for (const source of sources) {
      const visited = new Set([source.id]);
      findCyclesDFS(source.id, [source.id], visited);
    }

    function canReach(startId, targetId) {
      const queue = [startId];
      const visited = new Set([startId]);
      while (queue.length > 0) {
        const current = queue.shift();
        if (current === targetId) return true;
        const neighbors = Object.keys(citation_map[current]?.cites || {}).map(Number);
        for (const neighbor of neighbors) {
          if (!visited.has(neighbor)) { visited.add(neighbor); queue.push(neighbor); }
        }
      }
      return false;
    }

    const level0Sources = sources.filter(s => s.credibility_level === 0);
    let single_primary = null;
    if (sources.length >= 3) {
      for (const S0 of level0Sources) {
        const dependents = [];
        for (const S of sources) {
          if (S.id === S0.id) continue;
          if (S.credibility_level >= 1 && canReach(S.id, S0.id)) dependents.push(S.id);
        }
        if (dependents.length >= 3) {
          single_primary = {
            primary_source_id: S0.id,
            primary_title: S0.title,
            dependent_sources: dependents,
            warning: `MULTIPLE_SOURCES_SINGLE_PRIMARY: Sources [${dependents.join(', ')}] all derive from Source [${S0.id}].`
          };
          break;
        }
      }
    }

    return { citation_map, circular_chains, single_primary };
  }

  function makeFallbackRoutePlan() {
    const q = String(query || '').toLowerCase();
    let needClass = 'fact_pin', breadthMode = 'standard', exactnessMode = 'summary_safe', searchMode = 'single';
    if (outputIntent === 'CODE_BOILERPLATE' || /\b(code|snippet|function|class|interface|type|schema|sql|regex|implementation|api route|curl|command)\b/.test(q)) {
      needClass = 'code_extract'; breadthMode = 'exhaustive'; exactnessMode = 'raw_code';
    } else if (/\b(error|crash|workaround|fix|cannot|failed|looping|stuck|latency|dropout|buzzing|solved|remedy|registry|driver)\b/.test(q)) {
      needClass = 'forum_troubleshoot'; breadthMode = 'exhaustive'; exactnessMode = 'exact_spans'; searchMode = 'dual';
    } else if (outputIntent === 'VERBATIM_STATUTE' || /\b(verbatim|exact text|exact quote|quote|clause|section|article|statute|law|regulation|act|bill)\b/.test(q)) {
      needClass = 'verbatim_extract'; breadthMode = 'exhaustive'; exactnessMode = 'exact_spans';
    } else if (/\b(list all|full list|enumerate|every |exact option|allowed values|all flags|all params)\b/.test(q)) {
      needClass = 'enumeration_extract'; breadthMode = 'exhaustive'; exactnessMode = 'exact_spans';
    } else if (/\b(step by step|steps|procedure|migration steps|how do i|how to)\b/.test(q)) {
      needClass = 'procedure_extract'; breadthMode = 'exhaustive'; exactnessMode = 'exact_spans';
    } else if (/\b(compare|vs\b|versus|tradeoff|better|worse|pros and cons)\b/.test(q)) {
      needClass = 'tradeoff_map'; searchMode = 'dual';
    } else if (/\b(criticism|broken|bug|deprecated|issue|compatible|current|latest|support)\b/.test(q)) {
      needClass = 'version_pin'; searchMode = 'dual';
    }

    if (detailMode === 'MINIMAL') breadthMode = 'scalar';
    if (detailMode === 'EXHAUSTIVE' || detailMode === 'RAW_TEXT') breadthMode = 'exhaustive';
    if (detailMode === 'RAW_TEXT' && exactnessMode === 'summary_safe') exactnessMode = 'exact_spans';

    return {
      need_class: needClass,
      breadth_mode: breadthMode,
      exactness_mode: exactnessMode,
      search_mode: searchMode,
      primary_query: query,
      adversarial_query: null,
      key_terms: tokenizeNeedles({ key_terms: [], need_class: needClass, breadth_mode: breadthMode }),
      include_domains: [],
      exclude_domains: ['pinterest.com'],
      primary_results: breadthMode === 'exhaustive' ? 10 : 6,
      adversarial_results: 0,
      notes: []
    };
  }

  const routerSystem = `TEMPORAL GROUNDING: Today is ${today}. Current year is ${currentYear}.\n\nClassify the retrieval objective and formulate an execution plan. Output strictly valid JSON matching schema.`;
  const routerSchema = {
    type: 'OBJECT',
    properties: {
      need_class: { type: 'STRING', enum: ['fact_pin', 'version_pin', 'tradeoff_map', 'contradiction_audit', 'code_extract', 'verbatim_extract', 'enumeration_extract', 'procedure_extract', 'forum_troubleshoot'] },
      breadth_mode: { type: 'STRING', enum: ['scalar', 'standard', 'exhaustive'] },
      exactness_mode: { type: 'STRING', enum: ['summary_safe', 'exact_spans', 'raw_code'] },
      search_mode: { type: 'STRING', enum: ['single', 'dual'] },
      primary_query: { type: 'STRING' },
      adversarial_query: { type: 'STRING' },
      key_terms: { type: 'ARRAY', items: { type: 'STRING' } },
      include_domains: { type: 'ARRAY', items: { type: 'STRING' } },
      exclude_domains: { type: 'ARRAY', items: { type: 'STRING' } },
      primary_results: { type: 'INTEGER' },
      adversarial_results: { type: 'INTEGER' },
      notes: { type: 'ARRAY', items: { type: 'STRING' } }
    },
    required: ['need_class', 'breadth_mode', 'exactness_mode', 'search_mode', 'primary_query', 'adversarial_query', 'key_terms', 'include_domains', 'exclude_domains', 'primary_results', 'adversarial_results', 'notes']
  };

  const routerPrompt = `<retrieval_request>\n<query>${query}</query>\n<document_url>${documentUrl || 'NONE'}</document_url>\n<output_intent>${outputIntent || 'DEFAULT'}</output_intent>\n<detail_mode>${detailMode || 'AUTO'}</detail_mode>\n<context_metadata>${JSON.stringify(contextMetadata || {})}</context_metadata>\n</retrieval_request>`;

  let routePlanText = await callGemini(routerSystem, routerPrompt, routerSchema, 1536);
  let routePlan = null;
  try { routePlan = JSON.parse(routePlanText); } catch (e) { routePlan = makeFallbackRoutePlan(); }

  const isQuantitativeQuery = /\b(decade|history|years|growth|spending|budget|statistics|trend|gdp|population|rate)\b/i.test(query);
  if (isQuantitativeQuery) {
    routePlan.breadth_mode = 'exhaustive';
    if (routePlan.search_mode === 'single') {
      routePlan.search_mode = 'dual';
      routePlan.adversarial_query = routePlan.adversarial_query || `${query} analysis trends database`;
      routePlan.adversarial_results = 5;
    }
  }

  if (detailMode === 'MINIMAL') routePlan.breadth_mode = 'scalar';
  if (detailMode === 'EXHAUSTIVE' || detailMode === 'RAW_TEXT') routePlan.breadth_mode = 'exhaustive';
  if (detailMode === 'RAW_TEXT' && routePlan.exactness_mode === 'summary_safe') routePlan.exactness_mode = outputIntent === 'CODE_BOILERPLATE' ? 'raw_code' : 'exact_spans';

  if (!searchApiKey && !documentUrl) {
    const keyErrMsg = 'Search API Key is missing. Please configure "search_api_key" in settings or link EXA_API_KEY from Secret Vault.';
    if (actionOnError === 'throw_error_to_ui') throw new Error(keyErrMsg);
    return {
      completion_state: 'failed',
      transport_state: 'failed',
      failed_stage: 'missing_api_key',
      api_error: { has_error: true, error_type: 'MISSING_API_KEY', status_code: 401, tag: 'MISSING_KEY', message: keyErrMsg },
      error_diagnostic: `🚨 SEARCH CONFIGURATION ERROR: ${keyErrMsg}`,
      retrieval_state: { search_mode: routePlan.search_mode || 'single', branch_statuses: [{ branch: 'primary', status: 'failed', via: null, error: keyErrMsg }], missing_axes: ['primary_missing'] },
      degraded_manifest: { sources: [], evidence_lattice: [] }
    };
  }

  async function attemptSearch(endpointUrl, body) {
    let response;
    try {
      response = await fetch(endpointUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': searchApiKey },
        body: JSON.stringify(body)
      });
    } catch (netErr) {
      const err = new Error(`Network failure connecting to ${endpointUrl}: ${netErr.message}`);
      err.status = null; err.tag = 'NETWORK_ERROR'; err.rawServerMsg = netErr.message; throw err;
    }

    let respData = null, rawText = '';
    try { rawText = await response.text(); respData = JSON.parse(rawText); } catch (e) {}

    if (!response.ok) {
      const status = response.status;
      const tag = respData?.tag || respData?.error?.tag || '';
      const serverMsg = respData?.error?.message || (typeof respData?.error === 'string' ? respData.error : '') || respData?.message || rawText || response.statusText;
      if (status === 403 && (tag === 'SOURCE_NOT_AVAILABLE' || /SOURCE_NOT_AVAILABLE/i.test(serverMsg))) {
        if (body.includeDomains && body.includeDomains.length > 0) {
          const healedBody = { ...body };
          delete healedBody.includeDomains;
          return await attemptSearch(endpointUrl, healedBody);
        }
      }
      const err = new Error(`HTTP ${status}${tag ? ` [${tag}]` : ''}: ${serverMsg}`);
      err.status = status; err.tag = tag; err.rawServerMsg = serverMsg; throw err;
    }
    if (!respData || !Array.isArray(respData.results)) throw new Error(`Unexpected search response structure`);
    return respData.results;
  }

  async function runSearch(branch, searchQuery, numResults) {
    if (!searchQuery || !searchApiKey) return { branch, status: 'skipped', via: null, results: [], error: null, errorObj: null };
    const maxCharacters = routePlan.need_class === 'code_extract' || routePlan.need_class === 'forum_troubleshoot' ? 48000 : routePlan.breadth_mode === 'exhaustive' || isQuantitativeQuery ? 55000 : routePlan.need_class === 'fact_pin' ? 18000 : 30000;
    const body = {
      query: searchQuery,
      numResults: clamp(numResults || 6, 1, 15),
      type: 'auto',
      contents: { text: { maxCharacters }, highlights: { numSentences: routePlan.need_class === 'fact_pin' ? 3 : 6, highlightsPerUrl: 4 } }
    };
    const qLower = String(query || '').toLowerCase();
    if (/0x[0-9a-fA-F]+|\b(hkey_current_user|hkey_local_machine|regedit|system32|focusrite|asio|dpc|latency|dropout|buffer)\b/i.test(qLower) || routePlan.need_class === 'forum_troubleshoot') {
      body.type = 'keyword';
    }
    if (routePlan.need_class === 'forum_troubleshoot') body.category = 'forum';
    else if (qLower.includes('paper') || qLower.includes('study') || qLower.includes('biomarker') || routePlan.need_class === 'contradiction_audit') body.category = 'research paper';
    else if (qLower.includes('news') || qLower.includes('antitrust') || qLower.includes('court') || qLower.includes('lawsuit')) body.category = 'news';

    const includeDomains = toArray(routePlan.include_domains);
    const excludeDomains = toArray(routePlan.exclude_domains);
    if (includeDomains.length) body.includeDomains = includeDomains;
    if (excludeDomains.length) body.excludeDomains = excludeDomains;

    const endpoints = [];
    if (proxyBase) endpoints.push({ url: searchProxyUrl, via: 'proxy' });
    endpoints.push({ url: searchDirectUrl, via: 'direct' });

    let lastErrorObj = null;
    const errors = [];
    for (const endpoint of endpoints) {
      try {
        const results = await attemptSearch(endpoint.url, body);
        if (endpoint.via === 'direct') transportState = transportState === 'healthy' ? 'degraded' : transportState;
        return { branch, status: 'success', via: endpoint.via, results, error: null, errorObj: null };
      } catch (e) {
        lastErrorObj = { message: e.message, status: e.status || null, tag: e.tag || null, rawServerMsg: e.rawServerMsg || null, via: endpoint.via };
        errors.push(`[${endpoint.via}] ${e.message}`);
        if (e.status === 401 || e.status === 402 || e.tag === 'NO_MORE_CREDITS' || e.tag === 'INVALID_API_KEY') break;
      }
    }
    transportState = 'failed';
    return { branch, status: 'failed', via: null, results: [], error: errors.join('; ') || 'unknown_error', errorObj: lastErrorObj };
  }

  const branchRuns = await Promise.all([
    runSearch('primary', routePlan.primary_query, routePlan.primary_results),
    routePlan.search_mode === 'dual' ? runSearch('adversarial', routePlan.adversarial_query, routePlan.adversarial_results || 5) : Promise.resolve({ branch: 'adversarial', status: 'skipped', via: null, results: [], error: null, errorObj: null })
  ]);

  const branchStatuses = branchRuns.map(run => ({ branch: run.branch, status: run.status, via: run.via, error: run.error }));
  const allResults = [];
  branchRuns.forEach(run => (run.results || []).forEach(r => allResults.push({ ...r, branch: run.branch })));
  const failedRuns = branchRuns.filter(run => run.status === 'failed');

  // --- DOCUMENT HYDRATION ENGINE ---
  const hydratedSources = [];
  const targetDocUrls = [];
  if (documentUrl) targetDocUrls.push({ url: documentUrl, title: 'Explicit Target Document', branch: 'primary', isTarget: true });

  allResults.forEach(r => {
    const urlLower = String(r.url || '').toLowerCase();
    if (/\.(pdf|xlsx|xls|csv)(\?|$)/i.test(urlLower) || urlLower.includes('/pdf/')) {
      if (!targetDocUrls.some(t => t.url === r.url)) targetDocUrls.push({ url: r.url, title: r.title || 'Document File', branch: r.branch, isTarget: false });
    }
  });

  const docsToHydrate = targetDocUrls.slice(0, 2);
  if (docsToHydrate.length > 0) {
    const hydrationPromises = docsToHydrate.map(async (docMeta) => {
      try {
        const hydrated = await fetchAndHydrateDocument(docMeta.url);
        if (hydrated.success && hydrated.text) {
          const wsRef = (typeof workspace !== 'undefined' && workspace) || (resources && resources.workspace);
          if (wsRef && wsRef.writeFile) {
            const fileName = `doc_${safeDomain(docMeta.url)}_${Date.now()}.${hydrated.type === 'excel' ? 'csv' : 'txt'}`;
            try { await wsRef.writeFile(fileName, hydrated.text, 'in'); } catch (wsErr) {}
          }
          return {
            url: docMeta.url,
            title: `[HYDRATED ${hydrated.type.toUpperCase()}] ${docMeta.title}`,
            domain: safeDomain(docMeta.url),
            branch: docMeta.branch,
            text: hydrated.text,
            highlights: [],
            publishedDate: today,
            score: 100,
            role: 'official_document',
            is_hydrated: true,
            hydrated_type: hydrated.type
          };
        }
      } catch (e) {}
      return null;
    });
    const hydratedResults = (await Promise.all(hydrationPromises)).filter(Boolean);
    hydratedSources.push(...hydratedResults);
  }

  if (allResults.length === 0 && hydratedSources.length === 0) {
    if (failedRuns.length > 0) {
      const primaryErr = failedRuns.find(r => r.branch === 'primary') || failedRuns[0];
      const diagMessage = `🚨 SEARCH API ERROR: ${primaryErr.error || 'Search request failed'}`;
      if (actionOnError === 'throw_error_to_ui') throw new Error(diagMessage);
      return {
        completion_state: 'failed',
        transport_state: 'failed',
        failed_stage: 'search_api_error',
        api_error: { has_error: true, status_code: primaryErr.errorObj?.status || null, message: primaryErr.error },
        error_diagnostic: diagMessage,
        retrieval_state: { search_mode: routePlan.search_mode, branch_statuses: branchStatuses, missing_axes: ['primary_missing'] },
        degraded_manifest: { sources: [], evidence_lattice: [] }
      };
    }
    return {
      completion_state: 'degraded',
      transport_state: transportState,
      failed_stage: 'retrieval_empty',
      api_error: null,
      retrieval_state: { search_mode: routePlan.search_mode, branch_statuses: branchStatuses, missing_axes: ['primary_missing'] },
      error_diagnostic: 'Search completed successfully, but no web results matched the queries on any active branch.',
      degraded_manifest: { sources: [], evidence_lattice: [] }
    };
  }

  const byUrl = new Map();
  hydratedSources.forEach(doc => byUrl.set(normalizeUrl(doc.url), doc));
  for (const r of allResults) {
    const url = normalizeUrl(r.url);
    if (!url) continue;
    const domain = safeDomain(url);
    const existing = byUrl.get(url);
    const score = typeof r.score === 'number' ? r.score : 0;
    if (!existing || score > (existing.score || 0)) {
      byUrl.set(url, {
        url, title: r.title || domain, domain, branch: r.branch, text: cleanTextPreserveLines(r.text || ''),
        highlights: toArray(r.highlights), publishedDate: r.publishedDate || null, score, role: classifySourceRole(url, r.title), is_hydrated: false
      });
    }
  }

  const branchQuotas = (() => {
    if (routePlan.search_mode !== 'dual') return { primary: routePlan.breadth_mode === 'exhaustive' ? 12 : 8, adversarial: 0 };
    if (routePlan.need_class === 'contradiction_audit' || routePlan.need_class === 'tradeoff_map') return { primary: 6, adversarial: 6 };
    if (routePlan.need_class === 'forum_troubleshoot') return { primary: 7, adversarial: 5 };
    return { primary: 6, adversarial: 4 };
  })();

  const resultsByBranch = { primary: [], adversarial: [] };
  Array.from(byUrl.values()).forEach(item => {
    resultsByBranch[item.branch] = resultsByBranch[item.branch] || [];
    resultsByBranch[item.branch].push(item);
  });
  Object.keys(resultsByBranch).forEach(b => resultsByBranch[b].sort((x, y) => (y.score || 0) - (x.score || 0)));

  const finalSources = [];
  const domainCaps = {};
  function takeFromBranch(branch, limit) {
    const list = resultsByBranch[branch] || [];
    const maxCap = routePlan.need_class === 'forum_troubleshoot' ? 3 : 2;
    for (const item of list) {
      if (finalSources.length >= 12) break;
      domainCaps[item.domain] = domainCaps[item.domain] || 0;
      if (domainCaps[item.domain] >= maxCap && !item.is_hydrated) continue;
      if (finalSources.some(s => s.url === item.url)) continue;
      finalSources.push(item);
      domainCaps[item.domain] += 1;
      if (finalSources.filter(s => s.branch === branch).length >= limit) break;
    }
  }
  takeFromBranch('primary', branchQuotas.primary);
  takeFromBranch('adversarial', branchQuotas.adversarial);
  if (finalSources.length === 0) finalSources.push(...Array.from(byUrl.values()).slice(0, 10));

  const totalContextChars = routePlan.need_class === 'code_extract' || routePlan.need_class === 'forum_troubleshoot' || routePlan.need_class === 'verbatim_extract' ? 60000 : routePlan.breadth_mode === 'exhaustive' || isQuantitativeQuery ? 65000 : routePlan.need_class === 'fact_pin' ? 22000 : 38000;
  const dual = routePlan.search_mode === 'dual';
  let primaryRatio = dual ? 0.65 : 1;
  let adversarialRatio = dual ? 0.35 : 0;

  const perBranchBudget = {
    primary: Math.floor(totalContextChars * primaryRatio),
    adversarial: Math.floor(totalContextChars * adversarialRatio)
  };

  const sourceObjects = finalSources.map((source, idx) => {
    const credibility = classifySourceCredibility(source.url, source.title, source.text, source.is_hydrated);
    return {
      id: idx + 1, title: source.title, url: source.url, domain: source.domain, branch: source.branch, role: source.role,
      is_hydrated: source.is_hydrated || false, hydrated_type: source.hydrated_type || null, publishedDate: source.publishedDate,
      credibility_level: credibility.level, credibility_label: credibility.label, credibility_rationale: credibility.rationale,
      text: source.text, highlights: source.highlights
    };
  });

  const auditeeSources = sourceObjects.slice(0, 4);
  const siftSystemInstruction = `TEMPORAL GROUNDING: Today is ${today}. Current year is ${currentYear}.\n\nEvaluate source credibility using SIFT. Output strictly schema-compliant JSON.`;
  const siftSchema = {
    type: 'OBJECT',
    properties: {
      domain_authority: { type: 'STRING' },
      metrics: {
        type: 'OBJECT',
        properties: {
          epistemic_lateral_reputation_elr: { type: 'NUMBER' },
          consensus_semantic_coherence_csc: { type: 'NUMBER' },
          primary_source_closeness_psc: { type: 'NUMBER' },
          rhetorical_syntactic_saliency_rss: { type: 'NUMBER' },
          conflict_of_interest_coi: { type: 'NUMBER' }
        },
        required: ['epistemic_lateral_reputation_elr', 'consensus_semantic_coherence_csc', 'primary_source_closeness_psc', 'rhetorical_syntactic_saliency_rss', 'conflict_of_interest_coi']
      },
      overall_epistemic_weight: { type: 'NUMBER' },
      auditorial_advisory_for_parent_llm: { type: 'STRING' }
    },
    required: ['domain_authority', 'metrics', 'overall_epistemic_weight', 'auditorial_advisory_for_parent_llm']
  };

  const auditPromises = auditeeSources.map(async (source) => {
    const userPrompt = `<source_evaluation>\n<url>${source.url}</url>\n<is_hydrated_document>${source.is_hydrated}</is_hydrated_document>\n<raw_content>${truncate(source.text, 5000)}</raw_content>\n</source_evaluation>`;
    try {
      const auditJsonText = await callGemini(siftSystemInstruction, userPrompt, siftSchema, 1000);
      if (!auditJsonText) throw new Error('Empty audit');
      return { id: source.id, audit: JSON.parse(auditJsonText) };
    } catch (e) {
      const weight = source.credibility_level === 0 ? 0.95 : source.credibility_level === 1 ? 0.65 : 0.35;
      return {
        id: source.id,
        audit: {
          domain_authority: `${source.domain} (${source.credibility_label})`,
          metrics: { epistemic_lateral_reputation_elr: weight, consensus_semantic_coherence_csc: weight, primary_source_closeness_psc: weight, rhetorical_syntactic_saliency_rss: weight, conflict_of_interest_coi: weight },
          overall_epistemic_weight: weight,
          auditorial_advisory_for_parent_llm: `Authoritative ${source.credibility_label}. Safe to consume.`
        }
      };
    }
  });

  const auditResults = await Promise.all(auditPromises);
  const auditMap = new Map(auditResults.map(r => [r.id, r.audit]));

  sourceObjects.forEach(source => {
    let audit = auditMap.get(source.id);
    if (audit) {
      source.sift_audit = audit;
      source.credibility_level = audit.overall_epistemic_weight >= 0.75 ? 0 : audit.overall_epistemic_weight >= 0.45 ? 1 : 2;
      source.credibility_label = source.credibility_level === 0 ? 'Primary Source' : source.credibility_level === 1 ? 'Secondary Source' : 'Tertiary Source';
      source.credibility_rationale = audit.domain_authority;
    } else {
      const fallbackWeight = source.credibility_level === 0 ? 0.95 : source.credibility_level === 1 ? 0.65 : 0.35;
      source.sift_audit = {
        domain_authority: source.credibility_rationale,
        metrics: { epistemic_lateral_reputation_elr: fallbackWeight, consensus_semantic_coherence_csc: fallbackWeight, primary_source_closeness_psc: fallbackWeight, rhetorical_syntactic_saliency_rss: fallbackWeight, conflict_of_interest_coi: fallbackWeight },
        overall_epistemic_weight: fallbackWeight,
        auditorial_advisory_for_parent_llm: `Structural classification fallback: ${source.credibility_label}.`
      };
    }
  });

  const citationGraph = buildCitationGraph(sourceObjects);
  sourceObjects.forEach(source => {
    source.cites = citationGraph.citation_map[source.id]?.cites ? Object.keys(citationGraph.citation_map[source.id].cites).map(Number) : [];
    source.cited_by = [];
  });
  sourceObjects.forEach(sourceA => {
    (sourceA.cites || []).forEach(citedId => {
      const target = sourceObjects.find(s => s.id === citedId);
      if (target) { target.cited_by = target.cited_by || []; target.cited_by.push(sourceA.id); }
    });
  });

  const evidenceLattice = [];
  const branchMissingAxes = [];
  if (routePlan.search_mode === 'dual') {
    if (!sourceObjects.some(s => s.branch === 'primary')) branchMissingAxes.push('supporting_evidence_under_sampled');
    if (!sourceObjects.some(s => s.branch === 'adversarial')) branchMissingAxes.push('counterevidence_under_sampled');
  }

  const sourcesByBranch = { primary: sourceObjects.filter(s => s.branch === 'primary'), adversarial: sourceObjects.filter(s => s.branch === 'adversarial') };
  ['primary', 'adversarial'].forEach(branch => {
    const branchSources = sourcesByBranch[branch] || [];
    if (branchSources.length === 0) return;
    const branchBudget = branch === 'primary' ? perBranchBudget.primary : perBranchBudget.adversarial;
    const perSourceBudget = clamp(Math.floor(branchBudget / branchSources.length), 1800, 8000);
    branchSources.forEach(source => {
      const windows = selectWindowsForSource(source, routePlan, perSourceBudget);
      windows.forEach(w => evidenceLattice.push(w));
    });
  });

  if (evidenceLattice.length === 0) {
    sourceObjects.forEach(source => evidenceLattice.push({ sourceId: source.id, kind: 'support', text: truncate(source.text || '', 3000) }));
  }

  const ucsSystem = `TEMPORAL GROUNDING: Today is ${today}. Current year is ${currentYear}.\n\nSynthesize verified evidence, extract precise technical artifacts (exact parameters, tables, code, definitions), and construct an epistemic control layer. Output schema-compliant JSON.`;
  const ucsSchema = {
    type: 'OBJECT',
    properties: {
      epistemic_tension: { type: 'BOOLEAN' },
      preferred_action: { type: 'STRING' },
      required_caveat: { type: 'STRING' },
      actionability_limit: { type: 'STRING' },
      confidence_ceiling: { type: 'STRING', enum: ['High', 'Medium', 'Low'] },
      artifacts: {
        type: 'ARRAY',
        items: {
          type: 'OBJECT',
          properties: {
            kind: { type: 'STRING', enum: ['code', 'verbatim', 'steps', 'table', 'config', 'quote', 'command', 'signature', 'excerpt', 'solution'] },
            title: { type: 'STRING' },
            sourceIds: { type: 'ARRAY', items: { type: 'INTEGER' } },
            exactText: { type: 'STRING' },
            completeness: { type: 'STRING', enum: ['complete', 'partial'] },
            notes: { type: 'STRING' }
          },
          required: ['kind', 'title', 'sourceIds', 'exactText', 'completeness', 'notes']
        }
      },
      structured_items: {
        type: 'ARRAY',
        items: {
          type: 'OBJECT',
          properties: {
            item: { type: 'STRING' },
            sourceIds: { type: 'ARRAY', items: { type: 'INTEGER' } },
            confidence: { type: 'STRING', enum: ['High', 'Medium', 'Low'] }
          },
          required: ['item', 'sourceIds', 'confidence']
        }
      },
      claims: {
        type: 'ARRAY',
        items: {
          type: 'OBJECT',
          properties: {
            claim: { type: 'STRING' },
            sourceIds: { type: 'ARRAY', items: { type: 'INTEGER' } },
            lineage: { type: 'STRING' },
            confidence: { type: 'STRING', enum: ['High', 'Medium', 'Low'] }
          },
          required: ['claim', 'sourceIds', 'lineage', 'confidence']
        }
      },
      missing_facets: { type: 'ARRAY', items: { type: 'STRING' } }
    },
    required: ['epistemic_tension', 'preferred_action', 'required_caveat', 'actionability_limit', 'confidence_ceiling', 'artifacts', 'structured_items', 'claims', 'missing_facets']
  };

  const ucsPrompt = `<synthesis_task>\n<query>${query}</query>\n<document_url>${documentUrl || 'NONE'}</document_url>\n<output_intent>${outputIntent || 'DEFAULT'}</output_intent>\n<sources_matrix>\n${JSON.stringify(sourceObjects.map(({ id, title, url, domain, branch, role, is_hydrated, hydrated_type, credibility_label, sift_audit }) => ({ id, title, url, domain, branch, role, is_hydrated, hydrated_type, credibility_label, sift_audit })))}\n</sources_matrix>\n<evidence_lattice>\n${evidenceLattice.map(w => `--- SOURCE ${w.sourceId} | ${w.kind.toUpperCase()} ---\n${w.text}`).join('\n\n')}\n</evidence_lattice>\n</synthesis_task>`;

  const maxOutputTokens = routePlan.breadth_mode === 'exhaustive' ? 8192 : 4096;
  let ucsText = await callGemini(ucsSystem, ucsPrompt, ucsSchema, maxOutputTokens);

  function runHRP(rawText) {
    if (!rawText) return null;
    let clean = String(rawText).trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').replace(/,\s*([}\]])/g, '$1');
    const openBraces = (clean.match(/\{/g) || []).length, closeBraces = (clean.match(/\}/g) || []).length;
    const openBrackets = (clean.match(/\[/g) || []).length, closeBrackets = (clean.match(/\]/g) || []).length;
    if (openBrackets > closeBrackets) clean += ']'.repeat(openBrackets - closeBrackets);
    if (openBraces > closeBraces) clean += '}'.repeat(openBraces - closeBraces);
    return clean;
  }

  let finalPayload = null;
  try {
    const parsed = JSON.parse(runHRP(ucsText));
    if (parsed && typeof parsed.preferred_action === 'string') finalPayload = parsed;
  } catch (e) {}

  if (!finalPayload) {
    finalPayload = {
      epistemic_tension: branchMissingAxes.length > 0,
      preferred_action: 'Utilize verified evidence extracted directly from primary sources.',
      required_caveat: 'Cross-reference parameters with authoritative repositories.',
      actionability_limit: '',
      confidence_ceiling: 'High',
      artifacts: [],
      structured_items: [],
      claims: [],
      missing_facets: branchMissingAxes
    };
  }

  return {
    completion_state: (branchMissingAxes.length || finalPayload.missing_facets.length) ? 'partial' : 'healthy',
    transport_state: transportState,
    need_class: routePlan.need_class,
    breadth_mode: routePlan.breadth_mode,
    exactness_mode: routePlan.exactness_mode,
    retrieval_state: {
      search_mode: routePlan.search_mode,
      branch_statuses: branchStatuses,
      missing_axes: unique(branchMissingAxes),
      branch_errors: failedRuns.map(r => ({ branch: r.branch, error: r.error })),
      hydrated_documents_count: hydratedSources.length
    },
    control_layer: {
      epistemic_tension: finalPayload.epistemic_tension,
      preferred_action: finalPayload.preferred_action,
      required_caveat: finalPayload.required_caveat,
      actionability_limit: finalPayload.actionability_limit,
      confidence_ceiling: finalPayload.confidence_ceiling
    },
    data_layer: {
      sources: sourceObjects.map(({ id, title, url, domain, branch, role, is_hydrated, hydrated_type, publishedDate, credibility_level, credibility_label, credibility_rationale, cites, cited_by, sift_audit }) => ({ id, title, url, domain, branch, role, is_hydrated, hydrated_type, publishedDate, credibility_level, credibility_label, credibility_rationale, cites, cited_by, sift_audit })),
      artifacts: finalPayload.artifacts,
      structured_items: finalPayload.structured_items,
      claims: finalPayload.claims,
      missing_facets: unique(finalPayload.missing_facets)
    }
  };
}

